```latex
\section{Preliminaries}

\subsection{Notations and Terminology}
Throughout, we denote the undirected, weighted and colored input multi-graph by $G = (V,E,w,c)$, where $|V| = n$, $|E| = m$, $w: E \to \mathbb{R}_+$  is the weight function, and the coloring is $c: E \to C$ in the ECFT setting, or $c: V \to C$ in the VCFT setting
($C$ is the set of possible colors).
The fault parameter is a positive integer denoted by $f$. The stretch parameter is $(2k-1)$, where $k$ is a positive integer.
We mainly focus on the ECFT setting, unless explicitly stated otherwise. 

We say that a path collection is \emph{stemming from $v \in V$} if $v$ is the first vertex of every path in the collection. We usually denote such a path collection by $\pp_v$.
We say that a path collection is \emph{ending at $S \subseteq V$} if every path in the collection ends in a vertex from $S$.
For every vertex $s$, we denote by $\pp_{v,s}$ the set of paths in $\pp_v$ whose last vertex is $s$.
When $e$ is an edge with endpoint $v$, and $P$ is a path starting at $v$, we denote by $e \circ P$ the path obtained by concatenation of $e$ to $P$ through $v$. When $\pp_v$ is a path collection stemming from $v$, we denote $e \circ \pp_v = \{e \circ P \mid P \in \pp_v\}$. 
When $P$ is a path, $c(P)$ denotes the set of colors appearing on $P$.

\begin{definition}[Link]\label{def:link}
    When $\mathcal{P}$ is a path collection, and $J \subseteq C$ is a subset of colors, the $J$-link of $\pp$ is defined as
    $
    \pp[J] := \{ P \in \pp \mid  J \subseteq c(P)\}.
    $
\end{definition}

\subsection{An Alternative View of the Baswana-Sen Algorithm}\label{sect:baswana-sen}
The algorithm gradually constructs the spanner $H$ by adding edges.
It works in $k$ \emph{levels}, numbered $i=0,1,\dots,k-1$. 
Denote by $H_i$ the subgraph of $H$ consisting of all edges that were added in levels $0,1,\dots,i-1$, so the output is $H = H_k$.
Level $i$ has a corresponding set of $i$-\emph{centers} $S_i$, where $S_0 = V$, and $S_i$ is formed by sampling each $s \in S_{i-1}$ independently with probability $p = n^{-1/k}$.

The input for level $i$ is a set $E_i$ of \emph{undecided} edges, where $E_0 = E$.

\section{Parks: Color-Spread Path Collections}\label{sec:parks}

\begin{definition}[Score Function]\label{def:score}
    Let $\alpha>1$, $0<\beta \leq 1$.
    The \emph{$(\alpha,\beta)$-score function} $\sco^{\alpha,\beta}(\cdot)$ assigns a path $P$ with score
    $\sco^{\alpha,\beta} (P) := \beta (\alpha f)^{-|c(P)|}$.
    For $J \subseteq C$, the \emph{induced score function on $J$} is
    \[
    \sco^{\alpha,\beta}_J (P) := 
        \begin{cases}
            \beta (\alpha f)^{-|c(P)-J|} & \text{if $J \subseteq c(P)$,} \\
            0 & \text{if $J \not \subseteq c(P)$.}
        \end{cases}
    \]
    Thus, $\sco^{\alpha, \beta}_{\emptyset} (\cdot) = \sco^{\alpha, \beta}(\cdot)$.
    We extend this definition to a path collection $\pp$ in a linear fashion:
    $
    \sco^{\alpha, \beta}_J (\pp) := \sum_{P \in \pp}  \sco^{\alpha, \beta}_J (P).
    $
    Note that $\sco^{\alpha, \beta}_J (\pp) = \sco^{\alpha, \beta}_J (\pp[J])$.    
\end{definition}

\begin{definition}[Park]\label{def:park}
    A collection of paths $\pp$ is a \emph{park} with respect to some score function $\sco(\cdot)$, if for all $J \subseteq C$, it holds that $\sco_J (\pp) \leq 1$.
\end{definition}

\begin{definition}[$J$-Full Park]\label{def:full-park}
    Let $\pp$ be a park with respect to $\sco(\cdot)$, and let $J \subseteq C$ be a subset.
    We say $\pp$ is \emph{$J$-full} if $\sco_J (\pp) > 1/2$.
\end{definition}

\begin{definition}[Touristic Park]
    A path collection $\mathcal{P}_v$ stemming from a vertex $v \in V$ is a \emph{touristic park} with respect to global score $\gsco(\cdot)$ and local score $\lsco(\cdot)$, or a $(\gsco, \lsco)$-touristic park for short, if both following conditions hold:
    \begin{enumerate}
        \item \emph{(``Global'')} $\pp_v$ is a park with respect to $\gsco(\cdot)$.
        \item \emph{(``Local'')} For every $s \in V$, $\pp_{v,s}$ is a park with respect to $\lsco(\cdot)$.
    \end{enumerate}
\end{definition}

\section{The $f$-ECFT $(2k-1)$-Spanner Algorithm}

\subsection{Description of the Algorithm}\label{sect:alg-outline}
For each level $i$, we will have global and local score functions $\gsco^i(\cdot)$ and $\lsco^i(\cdot)$.
We maintain the following invariants:
\begin{enumerate}[label={({\bfseries I\arabic*})}]\item If $e = \{u,v\} \in E-E_i$, then for every set $F$ of at most $f$ colors not damaging $e$ (i.e., such that $c(e) \notin F$), it holds that $\dist_{H_i - F} (u,v) \leq (2i-1) w(e)$.\label{inv:I1}

    \item If $e = \{v,u\} \in E_i$, then there is a $(\gsco^i, \lsco^i)$-touristic park $\pp_u$ which consists of paths in $H_i$, each stemming from $u$, ending at some $i$-center from $S_i$, and having hop-length $i$, where each of the $i$ edges on the path weighs at most $w(e)$.
    Further, there exists $I \subseteq \{c(e)\}$ (i.e., $I = \emptyset$ or $I = \{c(e)\}$) such that $\pp_u$ is $I$-full (with respect to the score $\gsco^i(\cdot)$).\footnote{Note that both $\pp_u$ and $I$ depend on $e$ and on $i$, but we exclude these from the notation to avoid clutter. Additionally, note that this invariant holds for both endpoints of $e$ (namely, also with $v$ instead of $u$).}
    \label{inv:I2}

\end{enumerate}

\subsection{Choice of Parameters}\label{sect:params}

Let $D$ be a sufficiently large constant. For concreteness, $D=16$ suffices for us.
We define:
\begin{equation}\label{eq:param-def}
    \begin{matrix}
        \alpha_i       & := & D^{10k(4k-2i)}   & & & \beta_i       & := & D^{-2i} \\
        \hat{\alpha}_i & := & D^{10k(4k-2i-1)} & & & \hat{\beta}_i & := & D^{-2i-5}
    \end{matrix}
\end{equation}
and
\begin{equation}\label{eq:rho-def}
    \rho := p \cdot \frac{1}{\Theta( k(\log n + k^2) )} .
\end{equation}
Finally, we define the parameters of the used score functions as follows:
\begin{equation}\label{eq:scores-def}
    \begin{matrix}
       \gsco^i (\cdot) & := & \sco^{\alpha_i, \beta_i}(\cdot)   & & & \lsco^i (\cdot)       & := & \sco^{2,\beta_i}(\cdot) \\
    \pregsco^i (\cdot) & := & \sco^{\hat{\alpha}_i, \hat{\beta}_i \rho}(\cdot) & & & \prelsco^i (\cdot) & := & \sco^{2,\beta_i / D}(\cdot)
    \end{matrix}
\end{equation}

\section{The VCFT Setting}
\begin{itemize}
    \item \textbf{Sampling probability:}
    The probability of sampling a center is set to be $p\coloneqq (n/f)^{-1/k}$.

    \item \textbf{Invariant \ref{inv:I2}:} The only needed change in  \ref{inv:I2} is the definition of $I$. We require that $\{c(u)\}\subseteq I \subseteq \{c(v),c(u)\}$.
    The rest is the same, e.g., $\pp_u$ is still a $(\gsco^i,\lsco^i)$-touristic park.

\end{itemize}

\subsection{The Last Level}\label{sec:VCFT_last_level}
Recall that $E_{k-1}$ is the set of undecided edges which is the input of the last, $k-1$ level.

For a given vertex $v$, we now denote by $E_{k-1} (v)$ the set of all $E_{k-1}$ edges on which $v$ takes charge.

\paragraph{Execution of the Last Level.}
Similarly to the previous levels, we let each vertex $v$ process the edges in $E_{k-1} (v)$ in non-decreasing order of weight and partition them into $E_{k-1}(v, \keep)$ and $E_{k-1}(v,\safe)$ (this time there is no option to postpone), while gradually constructing the path collection $\prepp_v$.
We only maintain the property that for each $s \in S_{k-1}$, $\prepp_{v,s}$ is (locally) a park with respect to $\prelsco^{k-1}$.
When processing $e = \{v,u\} \in E_{k-1} (v)$, we partition the $\pp_u$ that is guaranteed by Invariant~\ref{inv:I2} for $e$ into $\pp_u^{\safe}$ and $\pp_u^{\keep}$ by the following voting process.
For $P \in \pp_u$ ending at the center $s \in S_{k-1}$:
\begin{itemize}
    \item \emph{(``Vote $\safe$'')} If there is $J \subseteq c(e \circ P)$ s.t.\ $\prepp_{v,s}$ is $J$-full (w.r.t.\ $\prelsco^{k-1}$), then $P \in \pp_u^{\safe}$.
    \item \emph{(``Vote $\keep$'')} Else, $P \in \pp_u^{\keep}$.
\end{itemize}
Again, $v$ puts $e$ in $E_i (v, \decision)$ where $\decision \in \{\keep, \safe\}$ is such that $\gsco^{k-1}_I (\pp_u^{\decision}) \geq 1/8$.
In case $\decision = \keep$, we also update $\prepp_v \gets \prepp_v \cup (e \circ \pp_u^{\keep})$.

\paragraph{Analysis.}
We partition the edges $e \in E_{k-1} (v, \keep)$ into two \emph{types}.
Consider $e = \{v,u\} \in E_{k-1} (v, \keep)$, and let $\{c(u)\} \subseteq I \subseteq \{c(v),c(u)\}$ be the set for which $\pp_u$ is $I$-full guaranteed by Invariant~\ref{inv:I2}.
If $|I|=1$, i.e., $I = \{c(u)\}$, we say that $e$ is of Type-$1$, and if $|I|=2$, i.e., $I=\{c(v),c(u)\}$ and $c(v)\neq c(u)$, we say it is of Type-$2$.
We denote the set of Type-$j$ edges by $E_{k-1} (v,\keep,j)$.
