ground_truth_solution:
We start by proving the following auxiliary statement:

\begin{restatable}[Concatenating an Edge]{claim}{concatedge}\label{clm:concat-edge}
    Let $\pp$ be a path collection that is stemming from an endpoint of an edge $e$.
    Let $\sco(\cdot)$ be an $(\alpha,\beta)$-score function, and let $J \subseteq C$.
    Then:
    \begin{enumerate}[label=(\arabic*)]
        \item $\sco_J(\pp) \leq \sco_{J\cup \{c(e)\}}(e \circ \pp)$.

        \item $\sco_J(e \circ \pp)\leq \sco_J(\pp) + \sco_{J-\{c(e)\}}(\pp)$. 
    \end{enumerate}
\end{restatable}
\begin{proof}[Proof of \Cref{clm:concat-edge}.]
    For (1), observe that $|c(e\circ P) - (J \cup \{c(e)\})| \leq |c(P) - J|$ for every $P \in \pp$, hence
    \begin{align*}
        \sco_J(\pp) 
        &= \sum_{P\in \pp[J]} \sco_J(P) \leq \sum_{P\in \pp[J]} \sco_{J \cup \{c(e)\}}(e\circ P)
        =\sum_{P'\in e\circ(\pp[J])} \sco_{J \cup \{c(e)\}}(P'), \\
        \shortintertext{which is, since $e\circ (\pp[J]) = (e \circ \pp)[J \cup \{c(e)\}]$,}
        &= \sum_{P'\in (e\circ\pp)[J\cup \{c(e)\}]} \sco_{J \cup \{c(e)\}}(P')
        = \sco_{J \cup \{c(e)\}}(e\circ \pp).
    \end{align*}

    For (2), we split to cases.
    The easy case is when $c(e) \notin J$.
    Then, we have $(e\circ \pp)[J] = e \circ (\pp[J])$. As adding colors to a path only reduces its score, we obtain that $\sco_J(e \circ \pp)\leq \sco_J(\pp)$, which is stronger than what we needed to prove.
    We now focus on the case when $c(e) \in J$.
    Denote $\pp_1 = \pp[J - \{c(e)\}] - \pp[J]$, and $\pp_2 = \pp[J]$.
    Then
    \begin{align*}
        \sco_J (e \circ \pp_1)
        =\sum_{P\in \pp_1} \beta (\alpha f)^{-|c(e\circ P) - J|}
        = \sum_{P \in \pp_1} \beta (\alpha f)^{-|c(P) - (J-\{c(e)\})|}
        = \sco_{J-\{c(e)\}} (\pp_1) ,
    \end{align*}
    and
    \begin{align*}
        \sco_J (e \circ \pp_2)
        =\sum_{P\in \pp_2} \beta (\alpha f)^{-|c(e\circ P) - J|}
        =\sum_{P\in \pp_2} \beta (\alpha f)^{-|c(P) - J|}
        =\sco_J (\pp_2).
    \end{align*}
    Note that $(e \circ \pp)[J] = e\circ \pp[J-\{c(e)\}] = (e \circ \pp_1) \cup (e \circ \pp_2)$.
    Hence,
    \begin{align*}
        \sco_J (e \circ \pp) 
        &= \sco_J (e \circ \pp_1) + \sco_J (e \circ \pp_2) \\
        &= \sco_{J-\{c(e)\}} (\pp_1) + \sco_J (\pp_2)
        \leq  \sco_{J-\{c(e)\}} (\pp) + \sco_J (\pp) ,
    \end{align*}
    as needed.
\end{proof}

With the above in mind, we are now ready to prove the main statement:

\begin{proof}
    We consider how the following quantity increases during the execution:
    \[
    \Phi := \sum_{s \in S_{k-1}} \prelsco^{k-1}_{\{c(v),c(s)\}} (\prepp_{v,s}) ~.
    \]
    As each $\prepp_{v,s}$ is locally a park throughout the execution, each term in the sum is at most $1$, so we have that $\Phi \leq |S_{k-1}|$, and $|S_{k-1}|$ is $np^{k-1} = O(f/p)$ in expectation and $O(np^{k-1} \log n) = O(f/p \cdot \log n)$ with high probability.
    Whenever we keep a Type-$1$ edge $e = \{v,u\}$, the increase in $\Phi$ is
        \begin{align*}
        &\sum_{s \in S_{k-1}} \prelsco^{k-1}_{\{c(v),c(s)\}}(e\circ \pp^{\keep}_{u,s}) \\
        &\geq \sum_{s \in S_{k-1}} \prelsco^{k-1}_{\{c(s)\}}(\pp^{\keep}_{u,s}) && \text{by \Cref{clm:concat-edge}(1),} \\
        &= \sum_{s \in S_{k-1}} \prelsco^{k-1}_{\{c(u)\}}(\pp^{\keep}_{u,s}) && \text{since $c(u),c(s) \in c(P)$ for $P\in \pp^{\keep}_{u,s}$,} \\
        &= \prelsco^{k-1}_{\{c(u)\}}(\pp^{\keep}_u) && \text{by linearity of score,} \\
        &\geq \frac{1}{D} \gsco^{k-1}_{\{c(u)\}}(\pp^{\keep}_u)&& \text{by choice of parameters (\Cref{eq:param-def}),} \\
        &\geq \Omega(1) && \text{as $\gsco_{\{c(u)\}}^{k-1}(\pp^{\keep}_u) \geq 1/8$, since $e$ is kept.}
    \end{align*}
    The lemma follows.
\end{proof}
